import { useMemo, useState } from 'react';
import {
  Activity, AlertTriangle, ArrowDown, ArrowUp, BarChart3, Bell, Beaker, BookOpen,
  BrainCircuit, Check, ChevronDown, CircleHelp, ClipboardCheck, Clock3, Code2,
  Download, ExternalLink, FileJson, FileText, Filter, FlaskConical, FolderKanban,
  GitCompareArrows, Grid2X2, Info, Layers3, LayoutDashboard, Menu, Moon, MoreHorizontal,
  Network, PanelLeftClose, PanelLeftOpen, Play, Plus, RefreshCw, Search, Settings2,
  ShieldCheck, SlidersHorizontal, Sparkles, Target, TestTube2, Upload, Users, X,
  Zap, type LucideIcon
} from 'lucide-react';
import './styles.css';
import './diversity.css';

type ViewKey = 'Dashboard' | 'Projects' | 'Targets' | 'Candidates' | 'Analyses' | '3D Structure Viewer' | 'Specificity' | 'Conformational Analysis' | 'Diversity' | 'Prioritization' | 'Candidate Ranking' | 'Experimental Feedback' | 'Failure Analysis' | 'Datasets' | 'Reports' | 'Settings' | 'Documentation';

type Candidate = {
  id: string; name: string; method: string; round: string; score: number; tier: 'HIGH' | 'MODERATE' | 'LOW';
  interfaceArea: number; hbonds: number; plddt: number; specificity: number; cluster: string;
  sequence: string; risk: string; riskTone: 'green' | 'amber' | 'red'; result?: string;
};

const candidates: Candidate[] = [
  { id: 'PDE-C0043', name: 'binder_043', method: 'Rosetta', round: 'round 04', score: 91, tier: 'HIGH', interfaceArea: 1658, hbonds: 8, plddt: 92.7, specificity: 57, cluster: 'C-03', sequence: 'MKTIIALSYIFCLVFADYKDDDDKAAEQLKEMLKKLE', risk: 'Low uncertainty', riskTone: 'green', result: 'Not tested' },
  { id: 'PDE-C0016', name: 'binder_016', method: 'AlphaFold-Multimer', round: 'round 02', score: 88, tier: 'HIGH', interfaceArea: 1617, hbonds: 9, plddt: 92.4, specificity: 58, cluster: 'C-01', sequence: 'MNNIRRVVPDGTTNAALELARRAGADVVVVEPG', risk: 'Low uncertainty', riskTone: 'green', result: 'Not tested' },
  { id: 'PDE-C0013', name: 'binder_013', method: 'RFdiffusion', round: 'round 01', score: 86, tier: 'HIGH', interfaceArea: 1552, hbonds: 7, plddt: 92.1, specificity: 61, cluster: 'C-02', sequence: 'MSTKELKQAIADLQKAGVEVVVNTDENGKVT', risk: 'Interface asymmetry', riskTone: 'amber', result: 'Not tested' },
  { id: 'PDE-C0017', name: 'binder_017', method: 'RFdiffusion', round: 'round 01', score: 84, tier: 'HIGH', interfaceArea: 1638, hbonds: 8, plddt: 92.8, specificity: 39, cluster: 'C-01', sequence: 'MKKLAVIGCGNIGTDQAAEAAKAGADVVVV', risk: 'Off-target signal', riskTone: 'amber', result: 'Not tested' },
  { id: 'PDE-C0018', name: 'binder_018', method: 'LigandMPNN', round: 'round 01', score: 82, tier: 'HIGH', interfaceArea: 1660, hbonds: 7, plddt: 93.3, specificity: 38, cluster: 'C-04', sequence: 'MSDLKSKLSELEKKLEKLGVEVVEAPNKK', risk: 'Off-target signal', riskTone: 'amber', result: 'Not tested' },
  { id: 'PDE-C0026', name: 'binder_026', method: 'ProteinMPNN', round: 'round 03', score: 79, tier: 'MODERATE', interfaceArea: 1489, hbonds: 6, plddt: 90.4, specificity: 64, cluster: 'C-05', sequence: 'MAVKDVKFGADKPEEVEALKKAGADVV', risk: 'State sensitivity', riskTone: 'amber', result: 'Not tested' },
  { id: 'PDE-C0039', name: 'binder_039', method: 'Rosetta', round: 'round 03', score: 76, tier: 'MODERATE', interfaceArea: 1432, hbonds: 5, plddt: 89.8, specificity: 70, cluster: 'C-06', sequence: 'MKKAIAVAGDSRVEALKKAGVEVVN', risk: 'Moderate confidence', riskTone: 'amber', result: 'Not tested' },
  { id: 'PDE-C0048', name: 'binder_048', method: 'LigandMPNN', round: 'round 04', score: 73, tier: 'MODERATE', interfaceArea: 1398, hbonds: 5, plddt: 88.5, specificity: 67, cluster: 'C-07', sequence: 'MARGKKIGYSAAEALKKAGADVVVV', risk: 'Flexible loop', riskTone: 'amber', result: 'Not tested' },
  { id: 'PDE-C0007', name: 'binder_007', method: 'ProteinMPNN', round: 'round 01', score: 66, tier: 'LOW', interfaceArea: 1281, hbonds: 3, plddt: 82.1, specificity: 72, cluster: 'C-08', sequence: 'MNVKDLATDVEKLAEAGADVV', risk: 'Clash + low pLDDT', riskTone: 'red', result: 'Not tested' },
  { id: 'PDE-C0031', name: 'binder_031', method: 'RFdiffusion', round: 'round 02', score: 62, tier: 'LOW', interfaceArea: 1204, hbonds: 4, plddt: 79.9, specificity: 55, cluster: 'C-09', sequence: 'MSTAEKLAKAGADVVVVEPG', risk: 'Missing residues', riskTone: 'red', result: 'Not tested' },
];

const navGroups: { label: string; items: { label: ViewKey; icon: LucideIcon; badge?: string }[] }[] = [
  { label: 'WORKSPACE', items: [
    { label: 'Dashboard', icon: LayoutDashboard }, { label: 'Projects', icon: FolderKanban },
    { label: 'Targets', icon: Target }, { label: 'Candidates', icon: Users, badge: '120' },
  ]},
  { label: 'ANALYSIS', items: [
    { label: 'Analyses', icon: Activity }, { label: '3D Structure Viewer', icon: Grid2X2 },
    { label: 'Specificity', icon: GitCompareArrows }, { label: 'Conformational Analysis', icon: Layers3 },
    { label: 'Diversity', icon: Network }, { label: 'Prioritization', icon: BarChart3 },
  ]},
  { label: 'LEARNING LOOP', items: [
    { label: 'Experimental Feedback', icon: FlaskConical, badge: '20' }, { label: 'Failure Analysis', icon: AlertTriangle },
    { label: 'Datasets', icon: Network },
  ]},
  { label: 'OUTPUT', items: [{ label: 'Reports', icon: FileText }, { label: 'Settings', icon: Settings2 }, { label: 'Documentation', icon: BookOpen }] }
];

const fmt = (n: number) => new Intl.NumberFormat('en-US').format(n);

function Badge({ children, tone = 'slate' }: { children: React.ReactNode; tone?: 'green' | 'amber' | 'red' | 'blue' | 'purple' | 'slate' }) {
  return <span className={`badge badge-${tone}`}>{children}</span>;
}

function ScoreBar({ value, tone = 'blue' }: { value: number; tone?: string }) {
  return <div className="scorebar"><span className={`scorebar-fill ${tone}`} style={{ width: `${value}%` }} /></div>;
}

function App() {
  const [active, setActive] = useState<ViewKey>('Dashboard');
  const [collapsed, setCollapsed] = useState(false);
  const [dark, setDark] = useState(false);
  const [search, setSearch] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [toast, setToast] = useState('');
  const [selectedIds, setSelectedIds] = useState<string[]>(['PDE-C0043', 'PDE-C0016']);
  const [budget, setBudget] = useState(10);

  const filteredCandidates = useMemo(() => candidates.filter(c => `${c.id} ${c.name} ${c.method} ${c.cluster}`.toLowerCase().includes(search.toLowerCase())), [search]);
  const showToast = (message: string) => { setToast(message); window.setTimeout(() => setToast(''), 3200); };
  const selectCandidate = (id: string) => setSelectedIds(s => s.includes(id) ? s.filter(x => x !== id) : [...s, id]);

  const exportData = (kind: 'CSV' | 'JSON' | 'FASTA') => {
    const data = kind === 'CSV'
      ? ['candidate_id,method,priority_score,interface_area,plddt,specificity,cluster', ...candidates.map(c => `${c.id},${c.method},${c.score},${c.interfaceArea},${c.plddt},${c.specificity},${c.cluster}`)].join('\n')
      : kind === 'FASTA' ? candidates.map(c => `>${c.id}|${c.method}|score=${c.score}\n${c.sequence}`).join('\n') : JSON.stringify({ project: 'PDE-2026-00017', exportedAt: new Date().toISOString(), candidates }, null, 2);
    const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([data], { type: 'text/plain' })); a.download = `protein-design-eval.${kind.toLowerCase()}`; a.click();
    showToast(`${kind} export prepared`);
  };

  return (
    <div className={`app ${dark ? 'theme-dark' : ''}`}>
      <aside className={`sidebar ${collapsed ? 'collapsed' : ''}`}>
        <div className="brand"><div className="brand-mark">PDE</div>{!collapsed && <div><strong>ProteinDesign</strong><span>-Eval</span></div>}<button className="icon-btn sidebar-toggle" onClick={() => setCollapsed(v => !v)}>{collapsed ? <PanelLeftOpen size={16}/> : <PanelLeftClose size={16}/>}</button></div>
        {!collapsed && <div className="project-switcher"><div className="project-icon">GP</div><div><small>ACTIVE PROJECT</small><strong>Human D2R de novo Miniprotein</strong><span>ID: PDE-2026-00017</span></div><ChevronDown size={14}/></div>}
        <nav>{navGroups.map(group => <div className="nav-group" key={group.label}>{!collapsed && <div className="nav-label">{group.label}</div>}{group.items.map(item => <button key={item.label} className={`nav-item ${active === item.label ? 'active' : ''}`} onClick={() => setActive(item.label)} title={collapsed ? item.label : undefined}><item.icon size={17}/>{!collapsed && <><span>{item.label}</span>{item.badge && <em>{item.badge}</em>}</>}</button>)}</div>)}</nav>
        {!collapsed && <div className="sidebar-bottom"><button className="new-analysis" onClick={() => { setActive('Analyses'); showToast('New analysis workspace opened'); }}><Plus size={15}/> New analysis</button><button className="demo-button" onClick={() => showToast('Demo GPCR data is already loaded')}>↻ Reload GPCR Demo</button><div className="user-chip"><div className="avatar">AS</div><div><strong>Amruta S.</strong><span>Research workspace</span></div><MoreHorizontal size={15}/></div></div>}
      </aside>
      <main className="main">
        <header className="topbar"><div className="mobile-brand"><Menu size={18}/><strong>ProteinDesign-Eval</strong></div><div className="breadcrumbs"><span>Projects</span><span>/</span><strong>{active}</strong></div><div className="top-actions"><button className="icon-btn" title="Search"><Search size={17}/></button><button className="icon-btn" title="Notifications"><Bell size={17}/><i className="notification-dot" /></button><button className="icon-btn" onClick={() => setDark(v => !v)} title="Toggle theme">{dark ? <Zap size={17}/> : <Moon size={17}/>}</button><div className="top-avatar">AS</div></div></header>
        <div className="content">
          {active === 'Dashboard' && <Dashboard setActive={setActive} showToast={showToast} />}
          {active === 'Candidates' && <CandidatesView candidates={filteredCandidates} search={search} setSearch={setSearch} selectedIds={selectedIds} selectCandidate={selectCandidate} setActive={setActive} onExport={exportData} showToast={showToast} />}
          {active === 'Analyses' && <AnalysesView showToast={showToast} />}
          {active === '3D Structure Viewer' && <ViewerView showToast={showToast} />}
          {active === 'Specificity' && <SpecificityView />}
          {active === 'Conformational Analysis' && <ConformationView />}
          {active === 'Diversity' && <DiversityView />}
          {(active === 'Prioritization' || active === 'Candidate Ranking') && <RankingView budget={budget} setBudget={setBudget} showToast={showToast} />}
          {active === 'Experimental Feedback' && <FeedbackView showToast={showToast} />}
          {active === 'Failure Analysis' && <FailureView />}
          {active === 'Projects' && <ProjectsView setActive={setActive} />}
          {active === 'Targets' && <TargetsView />}
          {active === 'Datasets' && <DatasetsView />}
          {active === 'Reports' && <ReportsView onExport={exportData} showToast={showToast} />}
          {active === 'Documentation' && <DocsView />}
          {active === 'Settings' && <SettingsView />}
        </div>
      </main>
      {showModal && <FeedbackModal close={() => setShowModal(false)} showToast={showToast} />}
      {toast && <div className="toast"><Check size={16}/>{toast}</div>}
    </div>
  );
}

function PageHeader({ eyebrow, title, description, action }: { eyebrow?: string; title: string; description?: string; action?: React.ReactNode }) {
  return <div className="page-header"><div><div className="eyebrow">{eyebrow || 'PDE-2026-00017 · DEMO GPCR PROJECT'}</div><h1>{title}</h1>{description && <p>{description}</p>}</div>{action}</div>;
}

function Dashboard({ setActive, showToast }: { setActive: (v: ViewKey) => void; showToast: (s: string) => void }) {
  return <><PageHeader title="Research Dashboard" description="Explainable prioritization for de novo D2R-targeting miniproteins." action={<div className="header-actions"><button className="btn btn-secondary" onClick={() => showToast('Report generation started')}><FileText size={15}/> Generate report</button><button className="btn btn-primary" onClick={() => setActive('Analyses')}><Plus size={15}/> New analysis</button></div>} />
    <div className="status-strip"><div className="status-live"><span className="pulse" /> ANALYSIS PIPELINE <strong>Completed</strong></div><span>Last run Sep 26, 2026 · 10:08 PM</span><button onClick={() => showToast('Pipeline is reproducible from analysis PDE-A-0042')}><Info size={14}/> Reproducibility info</button></div>
    <div className="kpi-grid"><Kpi label="ANALYZED CANDIDATES" value="120" note="100% processed successfully" icon={Users} tone="blue"/><Kpi label="HIGH PRIORITY SET" value="21" note="17.5% of total candidates" icon={Sparkles} tone="green"/><Kpi label="RECEPTOR CONFORMATIONS" value="3" note="Active · inactive · intermediate" icon={Layers3} tone="purple"/><Kpi label="EXPERIMENTAL FEEDBACK" value="20" note="8 hits · 12 failures" icon={FlaskConical} tone="orange"/></div>
    <section className="section-card tier-card"><div className="section-heading"><div><h2>Experimental prioritization tiers</h2><p>Transparent bands from the current weighted scoring configuration.</p></div><button className="text-btn" onClick={() => setActive('Candidate Ranking')}>View all candidates <ArrowUp size={13} className="rotate-45"/></button></div><Tier label="HIGH PRIORITY" tone="green" count="21 candidates" note="Strong interface packing, high backbone pLDDT, high predicted specificity" width={42}/><Tier label="MODERATE PRIORITY" tone="amber" count="42 candidates" note="Acceptable interface parameters, moderate conformational uncertainty" width={57}/><Tier label="LOW PRIORITY" tone="slate" count="57 candidates" note="Sub-optimal pLDDT, high predicted disorder, or off-target ambiguity" width={76}/></section>
    <div className="two-col"><section className="section-card philosophy"><div className="section-heading"><div><div className="tiny-label"><ShieldCheck size={14}/> SCIENTIFIC PHILOSOPHY</div><h2>Interpretability over certainty</h2></div><button className="icon-btn"><MoreHorizontal size={16}/></button></div><p>ProteinDesign-Eval does not promise guaranteed experimental binding. Every computational metric is transparently decomposed into interpretable evidence, and off-target discrimination.</p><div className="check-list"><span><Check size={13}/> Calculated biophysical metrics</span><span><Check size={13}/> Transparent multi-objective weights</span><span><Check size={13}/> Failure mode explainability</span></div><div className="card-foot">Target: ADRB2 (Class A GPCR)<button className="text-btn">Read principles <ArrowUp size={13} className="rotate-45"/></button></div></section><section className="section-card"><div className="section-heading"><div><h2>Workflow health</h2><p>Inputs and evidence across the closed loop.</p></div></div><div className="workflow"><WorkflowItem label="Upload + QC" state="Complete" done/><WorkflowItem label="Structure + interface" state="Complete" done/><WorkflowItem label="Specificity + states" state="Complete" done/><WorkflowItem label="Prioritization" state="Ready" done/><WorkflowItem label="Experimental feedback" state="20 results" done/></div></section></div>
    <LeadTable setActive={setActive}/>
  </>;
}

function Kpi({ label, value, note, icon: Icon, tone }: { label: string; value: string; note: string; icon: LucideIcon; tone: string }) { return <div className="kpi"><div className={`kpi-icon ${tone}`}><Icon size={17}/></div><div><span>{label}</span><strong>{value}</strong><small>{note}</small></div></div>; }
function Tier({ label, tone, count, note, width }: { label: string; tone: string; count: string; note: string; width: number }) { return <div className="tier"><div className={`tier-dot ${tone}`} /><div className="tier-copy"><div><strong>{label}</strong><span>{count}</span></div><p>{note}</p></div><div className="tier-bar"><span style={{ width: `${width}%` }} /></div><ChevronDown size={16}/></div>; }
function WorkflowItem({ label, state, done }: { label: string; state: string; done?: boolean }) { return <div className="workflow-item"><span className={done ? 'workflow-check' : 'workflow-pending'}>{done ? <Check size={11}/> : <Clock3 size={11}/>}</span><strong>{label}</strong><small>{state}</small></div>; }

function LeadTable({ setActive }: { setActive: (v: ViewKey) => void }) { return <section className="section-card table-card"><div className="section-heading"><div><h2>Lead prioritized candidates</h2><p>Top candidates ranked by multi-objective score (interface + pLDDT + specificity + diversity).</p></div><button className="text-btn" onClick={() => setActive('Candidate Ranking')}>Adjust ranking weights <SlidersHorizontal size={14}/></button></div><CandidateTable rows={candidates.slice(0, 5)} compact onSelect={() => setActive('Candidates')}/></section>; }

function CandidateTable({ rows, compact = false, onSelect }: { rows: Candidate[]; compact?: boolean; onSelect?: (id: string) => void }) {
  return <div className="table-wrap"><table><thead><tr><th>{!compact && <input type="checkbox"/>} Candidate</th><th>Design method</th><th>Priority</th><th>Interface Å²</th><th>H-bonds</th><th>pLDDT</th><th>Specificity</th><th>Status</th></tr></thead><tbody>{rows.map((c, i) => <tr key={c.id} onClick={() => onSelect?.(c.id)}><td><div className="candidate-cell">{!compact && <input type="checkbox" checked={false} readOnly/>}<span className="rank">{i + 1}</span><div><strong>{c.id}</strong><small>{c.name} · {c.round}</small></div></div></td><td><span className="method">{c.method}</span></td><td><Badge tone={c.tier === 'HIGH' ? 'green' : c.tier === 'MODERATE' ? 'amber' : 'slate'}>{c.score} · {c.tier}</Badge></td><td>{fmt(c.interfaceArea)}</td><td>{c.hbonds}</td><td><strong>{c.plddt}</strong></td><td><div className="table-score"><span>{c.specificity}%</span><ScoreBar value={c.specificity} tone={c.specificity > 55 ? 'green' : 'amber'}/></div></td><td><span className="status-dot"><i/> Ready</span></td></tr>)}</tbody></table></div>;
}

function CandidatesView({ candidates: rows, search, setSearch, selectedIds, selectCandidate, setActive, onExport, showToast }: { candidates: Candidate[]; search: string; setSearch: (s: string) => void; selectedIds: string[]; selectCandidate: (s: string) => void; setActive: (v: ViewKey) => void; onExport: (k: 'CSV'|'JSON'|'FASTA') => void; showToast: (s: string) => void }) {
  return <><PageHeader eyebrow="CANDIDATE LIBRARY · 120 TOTAL" title="Candidates" description="QC-validated designs with transparent, reproducible evidence across every analysis module." action={<div className="header-actions"><label className="btn btn-secondary"><Upload size={15}/> Upload candidates<input type="file" accept=".fasta,.fa,.pdb,.cif,.mmcif,.csv" hidden onChange={async e => { const file = e.target.files?.[0]; if (!file) return; const text = await file.text(); const sequenceFile = /\.(fasta|fa)$/i.test(file.name); const sequence = text.replace(/^>.*$/gm, '').replace(/\s/g, '').toUpperCase(); const invalid = sequenceFile && /[^ACDEFGHIKLMNPQRSTVWY]/.test(sequence); showToast(`${file.name}: ${sequenceFile ? `QC ${invalid ? 'flagged' : 'passed'}` : 'structure parsing queued'} · input ready for analysis`); }}/></label><button className="btn btn-secondary" onClick={() => onExport('FASTA')}><Download size={15}/> Export FASTA</button><button className="btn btn-primary" onClick={() => setActive('Analyses')}><Play size={15}/> Run analysis</button></div>} />
    <div className="candidate-controls"><div className="searchbox"><Search size={16}/><input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search candidate, method, cluster..." />{search && <button onClick={() => setSearch('')}><X size={14}/></button>}</div><button className="btn btn-secondary"><Filter size={15}/> Filters <span className="filter-count">3</span></button><button className="btn btn-secondary"><SlidersHorizontal size={15}/> Columns</button><span className="result-count">{rows.length} of 120 shown</span></div>
    <div className="notice"><Info size={15}/><div><strong>Computational evidence only</strong><span>Priority scores are not experimental success probabilities. Experimental evidence is shown separately when available.</span></div><button className="icon-btn"><X size={15}/></button></div>
    <section className="section-card table-card"><div className="section-heading"><div><h2>Candidate library</h2><p>Click a row to inspect sequence, structure, risk flags, and audit history.</p></div><div className="table-actions"><button className="icon-btn"><RefreshCw size={15}/></button><button className="icon-btn"><MoreHorizontal size={16}/></button></div></div><CandidateTable rows={rows} onSelect={selectCandidate}/><div className="table-footer"><span>{selectedIds.length} selected for comparison</span><div><button className="btn btn-secondary" onClick={() => setActive('3D Structure Viewer')}><Grid2X2 size={14}/> Compare structures</button><button className="btn btn-primary" onClick={() => setActive('Candidate Ranking')}><BarChart3 size={14}/> Prioritize selection</button></div></div></section>
  </>;
}

function AnalysesView({ showToast }: { showToast: (s: string) => void }) {
  return <><PageHeader eyebrow="ANALYSIS RUNS · PIPELINE" title="Analysis workspace" description="Run modular calculations with versioned inputs and reproducibility metadata." action={<button className="btn btn-primary" onClick={() => showToast('Analysis run queued — demo mode')}><Play size={15}/> Run new analysis</button>} /><div className="analysis-layout"><section className="section-card"><div className="section-heading"><div><h2>Analysis PDE-A-0042</h2><p>Demo GPCR evaluation · completed Sep 26, 2026 22:08</p></div><Badge tone="green"><Check size={12}/> Completed</Badge></div><div className="pipeline"><PipelineStep icon={ClipboardCheck} label="Input QC" note="120 / 120 passed" done/><PipelineStep icon={Code2} label="Sequence" note="Composition + clustering" done/><PipelineStep icon={Grid2X2} label="Structure" note="pLDDT, clashes, compactness" done/><PipelineStep icon={GitCompareArrows} label="Interface" note="Contacts + interaction map" done/><PipelineStep icon={ShieldCheck} label="Specificity" note="3 related receptors" done/><PipelineStep icon={Layers3} label="Conformation" note="3 target states" done/><PipelineStep icon={BarChart3} label="Ranking" note="Weights v2.1 applied" done/></div></section><section className="section-card run-meta"><div className="tiny-label">REPRODUCIBILITY</div><Meta label="Analysis ID" value="PDE-A-0042"/><Meta label="Pipeline version" value="0.4.1"/><Meta label="Structure model" value="AlphaFold 3 / 2025.1"/><Meta label="Input snapshot" value="120 candidates · 4 targets"/><Meta label="Parameters" value="weights-v2.1.json"/><button className="btn btn-secondary full" onClick={() => showToast('Re-run configured from saved snapshot')}><RefreshCw size={14}/> Re-run this analysis</button></section></div><section className="section-card"><div className="section-heading"><div><h2>Run history</h2><p>Every change is recorded in the audit trail.</p></div></div><div className="history-row"><span className="history-icon green"><Check size={14}/></span><div><strong>PDE-A-0042 · Current prioritization</strong><small>120 candidates · 7 modules · completed by Amruta S.</small></div><span>Sep 26, 2026 · 22:08</span><button className="text-btn">View audit trail</button></div><div className="history-row"><span className="history-icon blue"><RefreshCw size={14}/></span><div><strong>PDE-A-0038 · Added inactive state</strong><small>Recalculated conformational compatibility</small></div><span>Sep 24, 2026 · 16:42</span><button className="text-btn">View audit trail</button></div></section></>;
}
function PipelineStep({ icon: Icon, label, note, done }: { icon: LucideIcon; label: string; note: string; done?: boolean }) { return <div className="pipeline-step"><div className={`pipeline-icon ${done ? 'done' : ''}`}><Icon size={17}/>{done && <span><Check size={9}/></span>}</div><strong>{label}</strong><small>{note}</small></div>; }
function Meta({ label, value }: { label: string; value: string }) { return <div className="meta-row"><span>{label}</span><strong>{value}</strong></div>; }

function ViewerView({ showToast }: { showToast: (s: string) => void }) {
  return <><PageHeader eyebrow="STRUCTURE EXPLORER · PDB 8JTL" title="3D Structure Viewer" description="Inspect candidate–target geometry and interaction evidence in context." action={<div className="header-actions"><button className="btn btn-secondary" onClick={() => showToast('Structure snapshot exported')}><Download size={15}/> Export snapshot</button><button className="btn btn-primary"><Plus size={15}/> Add structure</button></div>} /><div className="viewer-layout"><section className="viewer-card"><div className="viewer-toolbar"><div><strong>PDE-C0043 · binder_043</strong><span>Target: ADRB2 active state · PDB 8JTL</span></div><div><button className="viewer-tool active">Cartoon</button><button className="viewer-tool">Surface</button><button className="viewer-tool">Contacts</button><button className="icon-btn"><MoreHorizontal size={16}/></button></div></div><div className="molecule"><div className="molecule-grid"/><div className="helix h1"/><div className="helix h2"/><div className="helix h3"/><div className="helix h4"/><div className="binder-shape"/><div className="contact c1"/><div className="contact c2"/><div className="contact c3"/><div className="mol-label target-label">ADRB2 · receptor</div><div className="mol-label binder-label">binder_043</div><div className="orientation">TOP VIEW <span>↻</span></div></div><div className="viewer-legend"><span><i className="legend-dot purple"/>Target receptor</span><span><i className="legend-dot cyan"/>Candidate binder</span><span><i className="legend-dot yellow"/>Interface contacts</span><span className="viewer-note"><Info size={13}/> Viewer illustration · calculated geometry</span></div></section><aside className="section-card structure-inspector"><div className="section-heading"><div><div className="tiny-label">SELECTED CANDIDATE</div><h2>PDE-C0043</h2><p>Rosetta · generation round 04</p></div><Badge tone="green">HIGH</Badge></div><div className="inspector-score"><span>Priority score</span><strong>91<small>/100</small></strong><ScoreBar value={91} tone="green"/></div><h3>Interface evidence</h3><Metric label="Interface area" value="1,658 Å²" source="Calculated"/><Metric label="Hydrogen bonds" value="8" source="Calculated"/><Metric label="Salt bridges" value="3" source="Calculated"/><Metric label="Interface pLDDT" value="91.4" source="Model-derived"/><h3>Risk flags</h3><div className="risk-line"><span className="risk-icon green"><Check size={12}/></span> No high-severity flags</div><div className="risk-line"><span className="risk-icon amber"><AlertTriangle size={12}/></span> State sensitivity: intermediate</div><button className="btn btn-secondary full">Open candidate detail <ExternalLink size={14}/></button></aside></div></>;
}
function Metric({ label, value, source }: { label: string; value: string; source: string }) { return <div className="metric-row"><span>{label}<small>{source}</small></span><strong>{value}</strong></div>; }

function SpecificityView() { return <><PageHeader eyebrow="SPECIFICITY · PRIMARY VS OFF-TARGETS" title="Specificity analysis" description="Compare the candidate interface against related receptors without conflating prediction with proof." action={<button className="btn btn-secondary"><Download size={15}/> Export matrix</button>} /><div className="callout blue"><ShieldCheck size={17}/><div><strong>How to read this view</strong><span>Higher discrimination means a larger difference between the primary target interface and the off-target interface. Values are calculated from the same pipeline and are not experimental specificity.</span></div></div><div className="specificity-grid"><section className="section-card"><div className="section-heading"><div><h2>Receptor discrimination matrix</h2><p>Mean interface compatibility across 120 candidates.</p></div><button className="text-btn">Methodology <CircleHelp size={14}/></button></div><div className="heatmap"><div className="heat-head"><span>Target state</span><span>ADRB2</span><span>DRD2</span><span>5HT2A</span><span>β1AR</span></div>{[['Active','92','88','63','57'],['Inactive','61','74','49','42'],['Intermediate','79','81','55','50']].map(row => <div className="heat-row" key={row[0]}><strong>{row[0]}</strong>{row.slice(1).map((v, i) => <span className={`heat-cell h${Math.round(Number(v) / 10)}`} key={i}>{v}%</span>)}</div>)}</div><div className="chart-legend"><span><i className="legend-dot dark-blue"/>Higher compatibility</span><span><i className="legend-dot pale-blue"/>Lower compatibility</span></div></section><section className="section-card specificity-side"><div className="section-heading"><div><h2>Lead candidate</h2><p>PDE-C0043 against related receptors</p></div><Badge tone="green">57% discrimination</Badge></div><div className="bar-list"><NamedBar label="Primary · ADRB2" value={91} tone="green"/><NamedBar label="DRD2 off-target" value={34} tone="amber"/><NamedBar label="5HT2A off-target" value={26} tone="blue"/><NamedBar label="β1AR off-target" value={18} tone="blue"/></div><div className="divider"/><Metric label="Interface residues shared" value="4 / 17" source="Calculated"/><Metric label="Off-targets evaluated" value="3" source="Input"/><Metric label="Uncertainty" value="Moderate" source="Model-derived"/></section></div></>; }
function NamedBar({ label, value, tone }: { label: string; value: number; tone: string }) { return <div className="named-bar"><div><span>{label}</span><strong>{value}%</strong></div><ScoreBar value={value} tone={tone}/></div>; }

function ConformationView() { return <><PageHeader eyebrow="CONFORMATION · 3 TARGET STATES" title="Conformational compatibility" description="Separate candidates that prefer one receptor state from those that remain compatible across the ensemble." action={<button className="btn btn-secondary"><Download size={15}/> Export state report</button>} /><div className="state-summary"><div><span className="state-mark active-state"/><strong>Active</strong><small>8JTL · agonist-bound</small></div><div><span className="state-mark inactive-state"/><strong>Inactive</strong><small>7JRO · antagonist-bound</small></div><div><span className="state-mark intermediate-state"/><strong>Intermediate</strong><small>8JTP · apo-like</small></div><div className="state-summary-note"><Info size={15}/> Compatibility is calculated from interface geometry across states.</div></div><section className="section-card"><div className="section-heading"><div><h2>State compatibility map</h2><p>Top 10 candidates shown; classification uses relative compatibility thresholds.</p></div><div className="segmented"><button className="selected">Score</button><button>Class</button></div></div><div className="conformation-table"><div className="conf-head"><span>Candidate</span><span>Active</span><span>Inactive</span><span>Intermediate</span><span>Classification</span><span>Evidence</span></div>{candidates.slice(0, 7).map(c => <div className="conf-row" key={c.id}><strong>{c.id}<small>{c.method}</small></strong><div className="state-score"><i className="active-fill" style={{width: `${Math.min(100,c.score + 2)}%`}}/><span>{c.score + 2}</span></div><div className="state-score"><i className="inactive-fill" style={{width: `${c.score - 15}%`}}/><span>{c.score - 15}</span></div><div className="state-score"><i className="intermediate-fill" style={{width: `${c.score - 7}%`}}/><span>{c.score - 7}</span></div><Badge tone={c.id === 'PDE-C0043' || c.id === 'PDE-C0016' ? 'blue' : 'amber'}>{c.id === 'PDE-C0043' ? 'State-selective' : 'Broad'}</Badge><span className="evidence-text">{c.score > 80 ? 'Strong geometry' : 'Moderate geometry'}</span></div>)}</div></section></>; }

function DiversityView() {
  return <><PageHeader eyebrow="DIVERSITY · REDUNDANCY DETECTOR" title="Candidate diversity" description="Keep the experimental shortlist broad enough to learn from different sequence and structure families." action={<button className="btn btn-secondary"><Download size={15}/> Export similarity matrix</button>} /><div className="diversity-kpis"><div className="diversity-stat"><span>SEQUENCE CLUSTERS</span><strong>9</strong><small>Calculated · 120 candidates</small></div><div className="diversity-stat"><span>STRUCTURE CLUSTERS</span><strong>7</strong><small>Calculated · backbone RMSD</small></div><div className="diversity-stat"><span>SHORTLIST REDUNDANCY</span><strong>18%</strong><small className="green-text">Within recommended range</small></div></div><div className="two-col"><section className="section-card"><div className="section-heading"><div><h2>Cluster coverage</h2><p>Each bar shows candidates available in a sequence family.</p></div><Badge tone="blue">9 clusters</Badge></div><div className="cluster-list">{[['C-01','Alpha-helical core','28',92],['C-02','Compact charged surface','21',71],['C-03','Loop-forward interface','17',58],['C-04','Mixed secondary structure','14',48],['C-05','Other families','40',82]].map(c => <div className="cluster-row" key={c[0]}><span className="cluster-id">{c[0]}</span><div><strong>{c[1]}</strong><ScoreBar value={Number(c[3])} tone="blue"/></div><b>{c[2]}</b></div>)}</div></section><section className="section-card"><div className="section-heading"><div><h2>Redundancy detector</h2><p>Current proposed shortlist · 10 candidates</p></div><Badge tone="green"><Check size={12}/> Healthy</Badge></div><div className="redundancy-ring"><div><strong>18%</strong><small>pairwise redundancy</small></div></div><p className="center-note">No two selected candidates exceed the 0.80 similarity threshold. C-03 adds a distinct family.</p><button className="btn btn-secondary full">Review pairwise matrix <GitCompareArrows size={14}/></button></section></div><section className="section-card"><div className="section-heading"><div><h2>Similarity matrix</h2><p>Selected candidates are separated by cluster, not only by score.</p></div><button className="text-btn">Open full matrix <ArrowUp size={13} className="rotate-45"/></button></div><div className="mini-matrix">{['043','016','013','017','018','026'].map((x, i) => <div key={x} className={`matrix-cell m${(i * 2 + 3) % 5}`}>{x}</div>)}</div></section></>;
}

function RankingView({ budget, setBudget, showToast }: { budget: number; setBudget: (n: number) => void; showToast: (s: string) => void }) {
  const [weights, setWeights] = useState({ structure: 20, interface: 20, specificity: 15, conformation: 15, diversity: 15, uncertainty: 10, feasibility: 5 });
  const total = Object.values(weights).reduce((a, b) => a + b, 0);
  return <><PageHeader eyebrow="PRIORITIZATION · WEIGHTS V2.1" title="Candidate ranking" description="Build an auditable, diversity-aware experimental shortlist from calculated evidence." action={<div className="header-actions"><button className="btn btn-secondary" onClick={() => showToast('Ranking JSON exported')}><Download size={15}/> Export ranking</button><button className="btn btn-primary" onClick={() => showToast(`${budget}-candidate shortlist saved`)}><Check size={15}/> Save shortlist</button></div>} /><div className="ranking-layout"><section className="section-card weights-card"><div className="section-heading"><div><h2>Scoring configuration</h2><p>Adjust weights; scores recalculate locally. Total must equal 100%.</p></div><Badge tone={total === 100 ? 'green' : 'amber'}>{total}% total</Badge></div>{(Object.keys(weights) as (keyof typeof weights)[]).map(key => <div className="weight-row" key={key}><div><strong>{key[0].toUpperCase() + key.slice(1)}</strong><span>{key === 'uncertainty' ? 'Reward interpretable, bounded uncertainty' : key === 'diversity' ? 'Penalize redundancy in shortlist' : `Contribution of ${key} evidence`}</span></div><input type="range" min="0" max="40" value={weights[key]} onChange={e => setWeights({ ...weights, [key]: Number(e.target.value) })}/><b>{weights[key]}%</b></div>)}<div className="weight-foot"><span><Info size={14}/> Weight changes are recorded in the audit trail.</span><button className="text-btn" onClick={() => setWeights({ structure: 20, interface: 20, specificity: 15, conformation: 15, diversity: 15, uncertainty: 10, feasibility: 5 })}>Reset defaults</button></div></section><section className="section-card budget-card"><div className="section-heading"><div><h2>Experimental budget</h2><p>Balance quality, uncertainty, and redundancy.</p></div><Beaker size={18} className="heading-icon"/></div><div className="budget-options">{[10,25,50].map(n => <button className={budget === n ? 'selected' : ''} onClick={() => setBudget(n)} key={n}><strong>{n}</strong><span>candidates</span></button>)}</div><div className="budget-result"><span>Diversity-aware recommendation</span><strong>{budget} candidates</strong><div className="budget-bar"><i style={{width: `${budget === 10 ? 34 : budget === 25 ? 62 : 88}%`}}/></div><small>{budget === 10 ? '2 per cluster · 3 uncertainty probes' : budget === 25 ? 'Coverage across 9 clusters · 6 uncertainty probes' : 'Broad coverage · higher experimental load'}</small></div><button className="btn btn-primary full" onClick={() => showToast(`Optimized ${budget}-candidate shortlist`)}><Sparkles size={15}/> Optimize shortlist</button></section></div><div className="two-col"><section className="section-card"><div className="section-heading"><div><h2>Pareto front</h2><p>Non-dominated candidates across interface, specificity, and uncertainty.</p></div><Badge tone="blue">18 candidates</Badge></div><div className="scatter"><div className="axis-y">specificity ↑</div><div className="scatter-points">{candidates.map((c, i) => <span key={c.id} className={c.tier === 'HIGH' ? 'point high' : 'point'} style={{ left: `${18 + i * 8}%`, bottom: `${15 + c.specificity / 1.3}%` }} title={c.id}/>)}</div><div className="axis-x">interface area →</div></div></section><section className="section-card shortlist-card"><div className="section-heading"><div><h2>Why selected?</h2><p>Explanation for PDE-C0043</p></div><Badge tone="green">Score 91</Badge></div><div className="why-item"><span className="why-number">01</span><div><strong>Strong interface geometry</strong><p>1,658 Å² buried area and 8 hydrogen bonds place it in the top 8%.</p></div></div><div className="why-item"><span className="why-number">02</span><div><strong>Low model uncertainty</strong><p>Backbone pLDDT 92.7 with no unresolved interface residues.</p></div></div><div className="why-item"><span className="why-number">03</span><div><strong>Adds cluster coverage</strong><p>Cluster C-03 is not represented by the other selected candidates.</p></div></div><div className="why-warning"><AlertTriangle size={14}/> Computational prioritization, not experimental success probability.</div></section></div></>; }

function FeedbackView({ showToast }: { showToast: (s: string) => void }) {
  return <><PageHeader eyebrow="LEARNING LOOP · 20 RESULTS" title="Experimental feedback" description="Bring measured outcomes back into the evidence graph without rewriting the original predictions." action={<div className="header-actions"><button className="btn btn-secondary"><Upload size={15}/> Import CSV</button><button className="btn btn-primary" onClick={() => showToast('Result entry form opened')}><Plus size={15}/> Add result</button></div>} /><div className="feedback-kpis"><Kpi label="BINDING HITS" value="8" note="40% of tested candidates" icon={Check} tone="green"/><Kpi label="EXPRESSION POSITIVE" value="14" note="70% of tested candidates" icon={Activity} tone="blue"/><Kpi label="SPECIFICITY HITS" value="6" note="Measured against off-target" icon={ShieldCheck} tone="purple"/><Kpi label="UNRESOLVED" value="2" note="Awaiting assay readout" icon={Clock3} tone="orange"/></div><section className="section-card table-card"><div className="section-heading"><div><h2>Outcome register</h2><p>Experimental records are immutable inputs to failure analysis and future recalibration.</p></div><Badge tone="blue">Experimental</Badge></div><div className="feedback-table"><div className="feedback-head"><span>Candidate</span><span>Binding</span><span>Kd / affinity</span><span>Expression</span><span>Specificity</span><span>Assay context</span></div>{[['PDE-C0003','Hit','18 nM','Positive','Pass','SPR · 25°C'],['PDE-C0008','Hit','42 nM','Positive','Pass','BLI · 25°C'],['PDE-C0011','Fail','—','Positive','—','SPR · 25°C'],['PDE-C0019','Hit','76 nM','Positive','Fail','Cell assay'],['PDE-C0022','Fail','—','Negative','—','Expression screen'],['PDE-C0030','Pending','—','Positive','Pending','SPR · queued']].map((r, i) => <div className="feedback-row" key={i}><strong>{r[0]}</strong><Badge tone={r[1] === 'Hit' ? 'green' : r[1] === 'Fail' ? 'red' : 'amber'}>{r[1]}</Badge><span>{r[2]}</span><span>{r[3]}</span><span>{r[4]}</span><small>{r[5]}</small><button className="icon-btn"><MoreHorizontal size={15}/></button></div>)}</div></section><div className="callout purple"><BrainCircuit size={18}/><div><strong>Closed-loop learning is ready for more data</strong><span>There are 20 experimental outcomes. Outcome prediction and model recalibration stay disabled until sufficient labeled data and validation are available.</span></div><button className="btn btn-secondary" onClick={() => showToast('Learning readiness report generated')}>View readiness</button></div></>; }

function FailureView() { return <><PageHeader eyebrow="FAILURE ANALYSIS · ASSOCIATION ONLY" title="Failure analysis" description="Find recurring patterns associated with failed outcomes. Associations are not causal claims." action={<button className="btn btn-secondary"><Download size={15}/> Export analysis</button>} /><div className="callout amber"><AlertTriangle size={17}/><div><strong>Interpret with care</strong><span>Patterns below are descriptive associations in the current demo dataset. They do not establish why a candidate failed.</span></div></div><div className="failure-grid"><section className="section-card"><div className="section-heading"><div><h2>Observed failure associations</h2><p>12 failed or partially failed experimental records.</p></div><button className="text-btn">Change cohort <Filter size={13}/></button></div><FailurePattern label="Low expression" count="7 / 12" percent={58} detail="Associated with high hydrophobic fraction > 0.42" tone="red"/><FailurePattern label="No measurable binding" count="5 / 12" percent={42} detail="Associated with interface area < 1,350 Å²" tone="amber"/><FailurePattern label="Off-target signal" count="4 / 12" percent={33} detail="Associated with specificity score < 45%" tone="purple"/><FailurePattern label="Unexpected state response" count="3 / 12" percent={25} detail="Associated with intermediate-state compatibility" tone="blue"/></section><section className="section-card"><div className="section-heading"><div><h2>Failure memory</h2><p>Previous failures to consider before selecting.</p></div><BrainCircuit size={18} className="heading-icon"/></div><div className="memory-card"><div className="memory-head"><span className="risk-icon red"><AlertTriangle size={13}/></span><strong>Hydrophobic patch near N-terminus</strong></div><p>6 candidates with this motif had negative expression or solubility readouts.</p><div className="memory-meta"><span>Evidence: 6 records</span><Badge tone="red">Avoid / review</Badge></div></div><div className="memory-card"><div className="memory-head"><span className="risk-icon amber"><AlertTriangle size={13}/></span><strong>Low interface specificity margin</strong></div><p>Consider orthogonal off-target assays when calculated margin is below 20%.</p><div className="memory-meta"><span>Evidence: 4 records</span><Badge tone="amber">Monitor</Badge></div></div><button className="btn btn-secondary full"><Plus size={14}/> Add failure pattern</button></section></div></>; }
function FailurePattern({ label, count, percent, detail, tone }: { label: string; count: string; percent: number; detail: string; tone: string }) { return <div className="failure-pattern"><div className="failure-label"><span className={`failure-dot ${tone}`}/><strong>{label}</strong><b>{count}</b></div><ScoreBar value={percent} tone={tone}/><small>{detail}</small></div>; }

function ProjectsView({ setActive }: { setActive: (v: ViewKey) => void }) { return <><PageHeader eyebrow="WORKSPACE · 3 PROJECTS" title="Projects" description="Organize target systems, candidate libraries, analyses, and experimental feedback." action={<button className="btn btn-primary" onClick={() => setActive('Targets')}><Plus size={15}/> Create project</button>} /><div className="project-grid"><div className="project-card selected"><div className="project-card-top"><Badge tone="green">Active</Badge><MoreHorizontal size={16}/></div><div className="project-symbol">GP</div><h2>Human D2R de novo Miniprotein</h2><p>Primary: DRD2 · Class A GPCR</p><div className="project-stats"><span><strong>120</strong> candidates</span><span><strong>3</strong> states</span><span><strong>20</strong> results</span></div><button className="btn btn-secondary full" onClick={() => setActive('Dashboard')}>Open project</button></div><div className="project-card"><div className="project-card-top"><Badge>Planning</Badge><MoreHorizontal size={16}/></div><div className="project-symbol orange">EN</div><h2>Enzyme binder pilot</h2><p>Primary: TBD · Beta project</p><div className="project-stats"><span><strong>0</strong> candidates</span><span><strong>0</strong> states</span><span><strong>0</strong> results</span></div><button className="btn btn-secondary full">Set up project</button></div><button className="new-project-card"><Plus size={20}/><strong>New project</strong><span>Start with a target system</span></button></div></>; }
function TargetsView() { return <><PageHeader eyebrow="TARGETS · 4 STRUCTURES" title="Target systems" description="Primary targets, conformational states, and optional off-targets used throughout the workflow." action={<button className="btn btn-primary"><Plus size={15}/> Add target</button>} /><div className="target-grid">{[['DRD2','Primary target','Active · Inactive · Intermediate','PDB 8JTL','primary'],['ADRB2','Related receptor','Active state','PDB 7JRO','related'],['5-HT2A','Off-target','Active state','UniProt P28223','off'],['β1-AR','Off-target','Inactive state','PDB 2Y03','off']].map(t => <div className="target-card" key={t[0]}><div className={`target-avatar ${t[4]}`}>{t[0].slice(0,2)}</div><div><Badge tone={t[4] === 'primary' ? 'green' : t[4] === 'related' ? 'blue' : 'slate'}>{t[1]}</Badge><h2>{t[0]}</h2><p>{t[2]}</p><small>{t[3]} · Validated</small></div><MoreHorizontal size={16}/></div>)}</div><section className="section-card"><div className="section-heading"><div><h2>Input validation</h2><p>All target identifiers were resolved before analysis.</p></div><Badge tone="green"><Check size={12}/> 4 / 4 valid</Badge></div><div className="validation-grid"><span><Check size={14}/> IDs resolved</span><span><Check size={14}/> Structures parseable</span><span><Check size={14}/> No duplicate targets</span><span><Check size={14}/> States labeled</span></div></section></>; }
function DatasetsView() { return <><PageHeader eyebrow="DATASETS · VERSIONED INPUTS" title="Datasets" description="Manage candidate libraries, target structures, and measured outcomes with provenance." action={<button className="btn btn-primary"><Upload size={15}/> Upload dataset</button>} /><div className="dataset-grid">{[['Candidate library · demo-gpcr-v4','120 candidates','FASTA + PDB bundle','Sep 26, 2026','green'],['Target conformations · drd2','3 structures','PDB / mmCIF','Sep 26, 2026','blue'],['Experimental outcomes · pilot-01','20 records','CSV · 8 hits / 12 fails','Sep 25, 2026','purple']].map(d => <div className="dataset-card" key={d[0]}><div className={`dataset-icon ${d[4]}`}><FileText size={18}/></div><div><h2>{d[0]}</h2><p>{d[1]} · {d[2]}</p><small>Updated {d[3]}</small></div><MoreHorizontal size={16}/></div>)}</div></>; }
function ReportsView({ onExport, showToast }: { onExport: (k: 'CSV'|'JSON'|'FASTA') => void; showToast: (s: string) => void }) { return <><PageHeader eyebrow="OUTPUT · REPRODUCIBLE REPORTS" title="Reports & exports" description="Package computational evidence, experimental outcomes, and reproducibility metadata for collaborators." action={<button className="btn btn-primary" onClick={() => showToast('PDF report generation started')}><FileText size={15}/> Generate PDF report</button>} /><div className="report-main"><section className="section-card report-preview"><div className="report-cover"><div className="report-mark">PDE</div><div className="eyebrow">RESEARCH REPORT · PDE-2026-00017</div><h2>Human D2R de novo<br/>Miniprotein Evaluation</h2><p>Computational prioritization and experimental feedback · v0.4.1</p><div className="report-cover-line"/><small>Prepared Sep 26, 2026 · Analysis PDE-A-0042</small></div><div className="report-sections"><span><Check size={13}/> Project + target context</span><span><Check size={13}/> QC + methodology</span><span><Check size={13}/> Interface + specificity</span><span><Check size={13}/> Prioritization + shortlist</span><span><Check size={13}/> Experimental results</span><span><Check size={13}/> Failure associations + limitations</span></div></section><section className="section-card export-card"><div className="section-heading"><div><h2>Quick exports</h2><p>Download the current evidence snapshot.</p></div><Download size={18} className="heading-icon"/></div><ExportRow icon={FileText} label="Full PDF report" note="Methodology + figures + limitations" action={() => showToast('PDF report generation started')}/><ExportRow icon={FileJson} label="Analysis JSON" note="Inputs, parameters, metrics, provenance" action={() => onExport('JSON')}/><ExportRow icon={Code2} label="Candidate CSV" note="All scores and risk flags" action={() => onExport('CSV')}/><ExportRow icon={Beaker} label="Structures + FASTA" note="Selected candidate bundle" action={() => onExport('FASTA')}/></section></div></>; }
function ExportRow({ icon: Icon, label, note, action }: { icon: LucideIcon; label: string; note: string; action: () => void }) { return <button className="export-row" onClick={action}><span className="export-icon"><Icon size={16}/></span><div><strong>{label}</strong><small>{note}</small></div><Download size={15}/></button>; }
function DocsView() { return <><PageHeader eyebrow="DOCUMENTATION · RESEARCH WORKFLOWS" title="Documentation" description="Understand what is calculated, what is model-derived, and what still needs an experiment." action={<button className="btn btn-secondary"><ExternalLink size={15}/> Open docs</button>} /><div className="docs-layout"><aside className="section-card docs-nav"><strong>Getting started</strong><span className="selected">Workflow overview</span><span>Input requirements</span><span>Reading priority scores</span><strong>Analysis modules</strong><span>Sequence + structure</span><span>Interface + specificity</span><span>Conformation + diversity</span><strong>Reproducibility</strong><span>Reports + exports</span><span>Audit trail</span></aside><section className="section-card docs-content"><div className="tiny-label">WORKFLOW OVERVIEW</div><h2>From designed sequence to informed experiment</h2><p>ProteinDesign-Eval combines orthogonal computational evidence into a transparent shortlist. It is designed to help researchers decide what to test next—not to replace the assay.</p><div className="doc-flow">{['Upload','QC','Analyze','Compare','Prioritize','Experiment','Learn'].map((x, i) => <span key={x}><b>{i + 1}</b>{x}{i < 6 && <ArrowDown size={13} className="rotate-neg-90"/>}</span>)}</div><h3>Result labels</h3><div className="label-explain"><Badge tone="blue">Calculated</Badge><span>Directly computed from supplied structures or sequences.</span><Badge tone="purple">Model-derived</Badge><span>Produced by a model or learned method; version is recorded.</span><Badge tone="green">Experimental</Badge><span>Manually entered or imported assay result.</span><Badge>Unavailable</Badge><span>Not enough input evidence to calculate safely.</span></div><div className="doc-warning"><AlertTriangle size={16}/><span>Computational prediction ≠ experimental proof. No metric in this app should be read as an experimental success probability.</span></div></section></div></>; }
function SettingsView() { return <><PageHeader eyebrow="SETTINGS · PROJECT CONFIGURATION" title="Settings" description="Configure project defaults, scoring policies, and reproducibility behavior." action={<button className="btn btn-primary"><Check size={15}/> Save changes</button>} /><div className="settings-layout"><section className="section-card settings-nav"><span className="selected"><FolderKanban size={15}/> Project</span><span><SlidersHorizontal size={15}/> Analysis defaults</span><span><ShieldCheck size={15}/> Validation rules</span><span><Users size={15}/> Team access</span><span><Code2 size={15}/> API + webhooks</span></section><section className="section-card settings-content"><h2>Project configuration</h2><p>Defaults apply to new analysis runs in this project.</p><label>Project name<input defaultValue="Human D2R de novo Miniprotein"/></label><label>Primary target<input defaultValue="DRD2 · human dopamine D2 receptor"/></label><label>Default pipeline version<select defaultValue="0.4.1"><option>0.4.1 · Current</option><option>0.3.8 · Archived</option></select></label><div className="toggle-row"><div><strong>Require reproducibility metadata</strong><small>Prevent analysis runs without pinned inputs and versions.</small></div><button className="toggle on"><i/></button></div><div className="toggle-row"><div><strong>Show unavailable metrics explicitly</strong><small>Never substitute missing evidence with a default value.</small></div><button className="toggle on"><i/></button></div><div className="audit-note"><ClipboardCheck size={16}/><div><strong>Audit trail enabled</strong><span>Parameter, weight, dataset, and analysis changes are recorded automatically.</span></div></div></section></div></>; }
function FeedbackModal({ close, showToast }: { close: () => void; showToast: (s: string) => void }) { return <div className="modal-backdrop"><div className="modal"><div className="modal-heading"><div><div className="eyebrow">EXPERIMENTAL · NEW RECORD</div><h2>Add experimental result</h2></div><button className="icon-btn" onClick={close}><X size={18}/></button></div><p>Experimental data is stored separately from computational predictions and will appear in the learning loop.</p><div className="form-grid"><label>Candidate ID<select defaultValue="PDE-C0043"><option>PDE-C0043</option><option>PDE-C0016</option><option>PDE-C0013</option></select></label><label>Binding result<select defaultValue="Hit"><option>Hit</option><option>Fail</option><option>Pending</option></select></label><label>Kd / affinity<input placeholder="e.g. 18 nM"/></label><label>Expression<select defaultValue="Positive"><option>Positive</option><option>Negative</option><option>Unknown</option></select></label><label>Specificity<select defaultValue="Pass"><option>Pass</option><option>Fail</option><option>Not tested</option></select></label><label>Conditions<input placeholder="e.g. SPR · 25°C"/></label></div><label>Notes<textarea placeholder="Assay context, caveats, or observations..." /></label><div className="modal-footer"><span><Info size={14}/> Label: Experimental</span><button className="btn btn-secondary" onClick={close}>Cancel</button><button className="btn btn-primary" onClick={() => { close(); showToast('Experimental result added to the register'); }}><Check size={15}/> Save result</button></div></div></div>; }

export default App;